SELECT * FROM Tasks WHERE Status <> 'Closed' OR Status IS NULL;

-- SQL Server 2022+ / PostgreSQL: porównanie NULL-safe
SELECT * FROM Tasks WHERE Status IS DISTINCT FROM 'Closed';

WITH r AS (
  SELECT Name, Salary,
         DENSE_RANK() OVER (ORDER BY Salary DESC) AS rnk
  FROM Employees
)
SELECT Name, Salary FROM r WHERE rnk = 2;

CREATE INDEX IX_Customers_LastName ON Customers (LastName);

-- seek: zejście po drzewie + odczyt zakresu liści
SELECT Id, LastName FROM Customers WHERE LastName LIKE 'Kow%';

SET XACT_ABORT ON;
BEGIN TRAN;
  UPDATE Accounts SET Balance -= 100 WHERE Id = 1;
  UPDATE Accounts SET Balance += 100 WHERE Id = 2;
COMMIT;

-- @table wcześniej sprawdzone z whitelistą
DECLARE @sql nvarchar(max) =
  N'SELECT Id, Name FROM dbo.' + QUOTENAME(@table) + N' WHERE Name = @name';
EXEC sp_executesql @sql, N'@name nvarchar(100)', @name = @name;

SELECT c.Id, c.Name
FROM Customers c
WHERE NOT EXISTS (
  SELECT 1 FROM Orders o WHERE o.CustomerId = c.Id
);

WITH d AS (
  SELECT Id, ROW_NUMBER() OVER (
           PARTITION BY Email ORDER BY CreatedAt, Id) AS rn
  FROM Customers
)
DELETE FROM d WHERE rn > 1;

ALTER TABLE Customers ADD CONSTRAINT UQ_Customers_Email UNIQUE (Email);

CREATE UNIQUE INDEX UX_Users_Pesel
  ON Users (Pesel) WHERE Pesel IS NOT NULL;

CREATE INDEX IX_Orders_CustomerId ON Orders (CustomerId);

-- przywrócenie zaufania po bulk load:
ALTER TABLE Orders WITH CHECK CHECK CONSTRAINT FK_Orders_Customers;

CREATE TABLE Events (
  Id         bigint IDENTITY PRIMARY KEY,
  OccurredAt datetimeoffset(3) NOT NULL,
  CreatedAt  datetime2(3) NOT NULL DEFAULT SYSUTCDATETIME(),
  EventDate  date NOT NULL
);

SELECT OccurredAt AT TIME ZONE 'Central European Standard Time' FROM Events;

SELECT s.name, sp.last_updated, sp.rows, sp.modification_counter
FROM sys.stats s
CROSS APPLY sys.dm_db_stats_properties(s.object_id, s.stats_id) sp
WHERE s.object_id = OBJECT_ID('dbo.Orders');

UPDATE STATISTICS dbo.Orders WITH FULLSCAN;

-- optymistycznie
UPDATE Products SET Price = @price
WHERE Id = @id AND RowVer = @rowVer;      -- kolumna rowversion
IF @@ROWCOUNT = 0 THROW 50001, 'Concurrency conflict', 1;

-- pesymistycznie (wewnątrz transakcji)
SELECT Stock FROM Products WITH (UPDLOCK, ROWLOCK) WHERE Id = @id;

-- często najlepiej: atomowy warunkowy UPDATE
UPDATE Products SET Stock = Stock - 1 WHERE Id = @id AND Stock > 0;

CREATE TABLE Prices (
  ProductId int PRIMARY KEY,
  Price     decimal(10,2) NOT NULL,
  ValidFrom datetime2 GENERATED ALWAYS AS ROW START,
  ValidTo   datetime2 GENERATED ALWAYS AS ROW END,
  PERIOD FOR SYSTEM_TIME (ValidFrom, ValidTo)
) WITH (SYSTEM_VERSIONING = ON (HISTORY_TABLE = dbo.PricesHistory));

SELECT * FROM Prices FOR SYSTEM_TIME AS OF '2025-06-01T00:00:00';

