SELECT CustomerId, SUM(Total) FROM Orders GROUP BY CustomerId;

DECLARE @Ids TABLE (Id int PRIMARY KEY);
INSERT INTO @Ids VALUES (1), (2), (3);

CREATE TABLE Orders (
  Id        uniqueidentifier NOT NULL
            CONSTRAINT DF_Orders_Id DEFAULT NEWSEQUENTIALID(),
  CreatedAt datetime2 NOT NULL,
  CONSTRAINT PK_Orders PRIMARY KEY CLUSTERED (Id)
);

CREATE INDEX IX_Orders_Pending
  ON Orders (CreatedAt) INCLUDE (CustomerId, Total)
  WHERE Status = 'Pending';

CREATE UNIQUE INDEX UX_Users_Email_Active
  ON Users (Email) WHERE IsDeleted = 0;

ALTER DATABASE Shop SET READ_COMMITTED_SNAPSHOT ON WITH ROLLBACK IMMEDIATE;
ALTER DATABASE Shop SET ALLOW_SNAPSHOT_ISOLATION ON;

SET TRANSACTION ISOLATION LEVEL SNAPSHOT;
BEGIN TRAN;
  SELECT SUM(Balance) FROM Accounts;   -- spójny obraz z początku transakcji
  SELECT COUNT(*) FROM Transfers;      -- ten sam moment w czasie
COMMIT;

SET XACT_ABORT ON;
BEGIN TRAN;
  UPDATE dbo.Stock WITH (UPDLOCK, SERIALIZABLE)
  SET Qty = @qty
  WHERE ProductId = @id;

  IF @@ROWCOUNT = 0
    INSERT dbo.Stock (ProductId, Qty) VALUES (@id, @qty);
COMMIT;

CREATE PARTITION FUNCTION pfMonthly (date)
  AS RANGE RIGHT FOR VALUES ('2026-01-01', '2026-02-01', '2026-03-01');
CREATE PARTITION SCHEME psMonthly
  AS PARTITION pfMonthly ALL TO ([PRIMARY]);

CREATE TABLE Events (
  Id        bigint NOT NULL,
  EventDate date NOT NULL,
  Payload   nvarchar(400),
  CONSTRAINT PK_Events PRIMARY KEY (EventDate, Id)
) ON psMonthly (EventDate);

